<?php
declare(strict_types=1);
$isHttps=isset($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!==''&&$_SERVER['HTTPS']!=='off';ini_set('session.use_strict_mode','1');session_name('coaching_tool_session');session_set_cookie_params(['httponly'=>true,'secure'=>$isHttps,'samesite'=>'Strict','path'=>'/']);session_start();header('Cache-Control: no-store, private');require_once dirname(__DIR__).'/app/bootstrap.php';
function designH(string|int|null $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$user=$_SESSION['user']??null;if(!is_array($user)||!isset($user['id'],$user['role'])||!in_array($user['role'],['coach','admin'],true)){header('Location: ./');exit;}$db=coachingDatabase();$uid=(int)$user['id'];$token=$_SESSION['csrf_token']??'';if(!is_string($token)||strlen($token)!==64){$token=bin2hex(random_bytes(32));$_SESSION['csrf_token']=$token;}
$fonts=['system'=>'Systemschrift','arial'=>'Arial','verdana'=>'Verdana','georgia'=>'Georgia','trebuchet'=>'Trebuchet MS'];$defaults=['schriftart'=>'system','schriftgroesse'=>16,'farbe_hintergrund'=>'#f5f7f5','farbe_flaeche'=>'#ffffff','farbe_text'=>'#1f302d','farbe_akzent'=>'#245c50','farbe_menue'=>'#173a33'];$notice='';$error='';
$q=$db->prepare('SELECT * FROM coaching_design_einstellungen WHERE benutzer_id=:id');$q->execute(['id'=>$uid]);$settings=array_merge($defaults,$q->fetch(PDO::FETCH_ASSOC)?:[]);
if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($token,(string)($_POST['csrf_token']??''))){http_response_code(400);exit('Ungültige Anfrage.');}
$input=['schriftart'=>(string)($_POST['schriftart']??''),'schriftgroesse'=>(int)($_POST['schriftgroesse']??0)];foreach(['hintergrund','flaeche','text','akzent','menue'] as $key){$input['farbe_'.$key]=(string)($_POST['farbe_'.$key]??'');}
$valid=array_key_exists($input['schriftart'],$fonts)&&$input['schriftgroesse']>=14&&$input['schriftgroesse']<=20;foreach(['farbe_hintergrund','farbe_flaeche','farbe_text','farbe_akzent','farbe_menue'] as $key)$valid=$valid&&preg_match('/^#[0-9A-Fa-f]{6}$/',$input[$key])===1;
if(!$valid)$error='Bitte prüfe Schriftart, Schriftgröße und Farben.';else{try{$s=$db->prepare('INSERT INTO coaching_design_einstellungen (benutzer_id,schriftart,schriftgroesse,farbe_hintergrund,farbe_flaeche,farbe_text,farbe_akzent,farbe_menue) VALUES (:id,:font,:size,:bg,:surface,:text,:accent,:menu) ON DUPLICATE KEY UPDATE schriftart=VALUES(schriftart),schriftgroesse=VALUES(schriftgroesse),farbe_hintergrund=VALUES(farbe_hintergrund),farbe_flaeche=VALUES(farbe_flaeche),farbe_text=VALUES(farbe_text),farbe_akzent=VALUES(farbe_akzent),farbe_menue=VALUES(farbe_menue)');$s->execute(['id'=>$uid,'font'=>$input['schriftart'],'size'=>$input['schriftgroesse'],'bg'=>$input['farbe_hintergrund'],'surface'=>$input['farbe_flaeche'],'text'=>$input['farbe_text'],'accent'=>$input['farbe_akzent'],'menu'=>$input['farbe_menue']]);header('Location: design-settings.php?saved=1');exit;}catch(Throwable $e){error_log('Design preference save failed: '.$e->getMessage());$error='Einstellungen konnten nicht gespeichert werden. Bitte Migration 005 einspielen.';}}
$settings=array_merge($settings,$input);
}if(isset($_GET['saved']))$notice='Deine Darstellung wurde gespeichert.';
?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Darstellung anpassen</title><link rel="stylesheet" href="assets/layout.css"><style>.page{max-width:900px;margin:auto;padding:34px clamp(24px,4vw,58px) 62px}.card{background:white;border:1px solid #e4ebe6;border-radius:14px;padding:22px;margin:20px 0}.form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.form label{display:grid;gap:7px;font-weight:600}.form select,.form input[type=number]{padding:10px;border:1px solid #dce5df;border-radius:8px;font:inherit}.form input[type=color]{width:100%;height:44px;border:0;background:none}.button{background:#245c50;color:white;border:0;border-radius:9px;padding:12px 16px;font:inherit}.notice,.error{padding:12px;border-radius:8px}.notice{background:#edf5ef}.error{background:#fff3f1}.preview{padding:18px;border-radius:12px;background:var(--theme-bg);color:var(--theme-text);font-family:var(--theme-font);font-size:var(--theme-size)}@media(max-width:650px){.form{grid-template-columns:1fr}}</style></head><body class="has-app-sidebar"><?php require_once dirname(__DIR__).'/app/navigation.php';renderCoachingSidebar($user,'design',$token);?><main class="page"><h1>Darstellung</h1><p>Wähle Schriftart, Schriftgröße und Farben für deinen Coach-Bereich. Deine Auswahl gilt auch im Klientenportal.</p><?php if($notice):?><p class="notice"><?=designH($notice)?></p><?php endif;?><?php if($error):?><p class="error"><?=designH($error)?></p><?php endif;?><section class="card"><form method="post" class="form"><input type="hidden" name="csrf_token" value="<?=designH($token)?>"><label>Schriftart<select name="schriftart"><?php foreach($fonts as $key=>$label):?><option value="<?=designH($key)?>" <?=$settings['schriftart']===$key?'selected':''?>><?=designH($label)?></option><?php endforeach;?></select></label><label>Grundschriftgröße<select name="schriftgroesse"><?php for($s=14;$s<=20;$s++):?><option value="<?=$s?>" <?= (int)$settings['schriftgroesse']===$s?'selected':'' ?>><?=$s?> px</option><?php endfor;?></select></label><?php $colors=['hintergrund'=>'Seitenhintergrund','flaeche'=>'Karten und Flächen','text'=>'Text','akzent'=>'Akzentfarbe und Schaltflächen','menue'=>'Seitenmenü'];foreach($colors as $key=>$label):?><label><?=designH($label)?><input type="color" name="farbe_<?=$key?>" value="<?=designH($settings['farbe_'.$key])?>"></label><?php endforeach;?><div><button class="button">Darstellung speichern</button></div></form></section><section class="card"><h2>Vorschau</h2><div class="preview">Beispieltext für deine Coaching-Oberfläche</div></section></main></body></html>